import java.util.Set;

public class AccessControlValidator {
    public static boolean hasSufficientPrivileges(Set<String> userPermissions, Set<String> requiredPermissions) {
        if (requiredPermissions == null || requiredPermissions.isEmpty()) {
            return true; // No permissions required
        }
        if (userPermissions == null || userPermissions.isEmpty()) {
            return false;
        }
        // containsAll checks if userPermissions is a superset of requiredPermissions
        return userPermissions.containsAll(requiredPermissions);
    }

    public static void main(String[] args) {
        Set<String> adminRights = Set.of("READ", "WRITE", "DELETE", "AUDIT");
        Set<String> editorRights = Set.of("READ", "WRITE");
        Set<String> financialActionRequirements = Set.of("WRITE", "AUDIT");

        System.out.println("Admin authorized?  " + 
            hasSufficientPrivileges(adminRights, financialActionRequirements)); // true
        System.out.println("Editor authorized? " + 
            hasSufficientPrivileges(editorRights, financialActionRequirements)); // false
    }
}

