import java.util.Set;

public class SubsetVerifier {
    public static boolean isSubsetOf(Set<String> sub, Set<String> superSet) {
        if (sub == null || sub.isEmpty()) return true;
        if (superSet == null) return false;
        return superSet.containsAll(sub);
    }
}

