import java.util.Set;
import java.util.HashSet;

public class SymmetricDifferenceFinder {
    public static Set<Integer> symmetricDifference(Set<Integer> setA, Set<Integer> setB) {
        Set<Integer> union = new HashSet<>();
        if (setA != null) union.addAll(setA);
        if (setB != null) union.addAll(setB);

        Set<Integer> intersection = new HashSet<>(setA != null ? setA : Set.of());
        if (setB != null) intersection.retainAll(setB);

        union.removeAll(intersection);
        return union;
    }
}
